// ── LOCAL PERSISTENCE ────────────────────────────────────────────────────
// Keeps created knowledge items and the in-progress "פריט ידע חדש" form
// draft across page refreshes by mirroring them into localStorage.
var NB_STORAGE_KEYS={docs:'wecom_kb_docs_v1',topics:'wecom_kb_topics_v1',draft:'wecom_kb_draft_v1',trash:'wecom_kb_trash_v1',seedVersion:'wecom_kb_seed_version_v1',history:'wecom_kb_history_v1'};
var NB_HISTORY_MAX=25;

function nbSaveLibrary(historyLabel){
  try{
    localStorage.setItem(NB_STORAGE_KEYS.docs, JSON.stringify(window.dynamicDocs||{}));
    localStorage.setItem(NB_STORAGE_KEYS.topics, JSON.stringify(TOPICS||[]));
    localStorage.setItem(NB_STORAGE_KEYS.trash, JSON.stringify(nbTrash||[]));
    localStorage.setItem(NB_STORAGE_KEYS.seedVersion, String(NB_SEED_VERSION));
  }catch(e){ /* localStorage unavailable — fail silently */ }
  nbSnapshotHistory(historyLabel);
  nbUpdateHistoryBadge();
}

// ── VERSION HISTORY ──────────────────────────────────────────────────────
// Every time the library is saved, a snapshot of the full state (topics +
// docs) is kept so unwanted changes can be found and reverted later. Rolling
// window — oldest snapshots drop off once the cap is reached.
function nbSnapshotHistory(label){
  try{
    var raw=localStorage.getItem(NB_STORAGE_KEYS.history);
    var history=raw?JSON.parse(raw):[];
    history.push({
      id:'hist-'+Date.now()+'-'+Math.floor(Math.random()*10000),
      ts:Date.now(),
      label:label||'עדכון בספרייה',
      topics:JSON.parse(JSON.stringify(TOPICS||[])),
      docs:JSON.parse(JSON.stringify(window.dynamicDocs||{}))
    });
    if(history.length>NB_HISTORY_MAX) history=history.slice(history.length-NB_HISTORY_MAX);
    localStorage.setItem(NB_STORAGE_KEYS.history, JSON.stringify(history));
  }catch(e){ /* storage full or unavailable — skip this snapshot silently */ }
}

function nbGetHistory(){
  try{
    var raw=localStorage.getItem(NB_STORAGE_KEYS.history);
    return raw?JSON.parse(raw):[];
  }catch(e){ return []; }
}

function nbUpdateHistoryBadge(){
  var badge=document.getElementById('nb-history-count-nav');
  if(!badge) return;
  var n=nbGetHistory().length;
  if(n){ badge.textContent=n; badge.style.display='inline-block'; }
  else{ badge.style.display='none'; }
}

function nbRestoreHistorySnapshot(histId){
  var history=nbGetHistory();
  var snap=history.find(function(h){return h.id===histId;});
  if(!snap) return;
  var dateStr=new Date(snap.ts).toLocaleDateString('he-IL')+' '+new Date(snap.ts).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});
  nbConfirmGeneric(
    'שחזור גרסה',
    'לשחזר את הספרייה למצב שהיה ב-<strong style="color:var(--navy)">'+dateStr+'</strong>?<br><span style="font-size:12px;color:var(--muted)">כל שינוי שנעשה אחרי הגרסה הזו יוחלף (אך יישמר כגרסה משלו, כך שגם את זה ניתן יהיה לבטל).</span>',
    'שחזר',
    'var(--navy)',
    function(){
      TOPICS=JSON.parse(JSON.stringify(snap.topics));
      window.dynamicDocs=JSON.parse(JSON.stringify(snap.docs));
      renderLibrary('all');
      renderHomeWaves();
      showView('library');
      nbSaveLibrary('שוחזר לגרסה מתאריך '+dateStr);
      nbUpdateTrashBadge();
      nbUpdateHistoryBadge();
      nbOpenHistory();
    }
  );
}

function nbOpenHistory(){
  var existing=document.getElementById('nb-history-overlay');
  if(existing) existing.remove();

  var overlay=document.createElement('div');
  overlay.id='nb-history-overlay';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px';

  var modal=document.createElement('div');
  modal.style.cssText='background:#fff;border-radius:16px;padding:22px;max-width:480px;width:100%;max-height:80vh;overflow-y:auto;font-family:Rubik,sans-serif;direction:rtl';

  var head=document.createElement('div');
  head.style.cssText='display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid var(--border)';
  head.innerHTML='<div style="font-size:16px;font-weight:700;color:var(--navy)">🕓 היסטוריית גרסאות</div>';

  var closeBtn=document.createElement('button');
  closeBtn.textContent='✕';
  closeBtn.style.cssText='background:none;border:none;font-size:16px;color:var(--muted);cursor:pointer;padding:4px 8px';
  closeBtn.addEventListener('click',function(){ overlay.remove(); });
  head.appendChild(closeBtn);

  var list=document.createElement('div');
  var history=nbGetHistory();
  if(!history.length){
    list.innerHTML='<div style="text-align:center;color:var(--muted);font-size:13.5px;padding:30px 10px">אין עדיין גרסאות שמורות</div>';
  } else {
    list.innerHTML=history.slice().reverse().map(function(snap){
      var d=new Date(snap.ts);
      var dateStr=d.toLocaleDateString('he-IL')+' '+d.toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});
      return '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 4px;border-bottom:1px solid var(--border)">'
        +'<div style="min-width:0"><div style="font-size:13.5px;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+snap.label+'</div>'
        +'<div style="font-size:11.5px;color:var(--muted);margin-top:2px">'+dateStr+'</div></div>'
        +'<button onclick="nbRestoreHistorySnapshot(\''+snap.id+'\')" style="height:32px;padding:0 14px;background:var(--navy);color:#fff;border:none;border-radius:7px;font-size:12.5px;font-weight:600;cursor:pointer;font-family:Rubik,sans-serif;flex-shrink:0">↩️ שחזר</button>'
        +'</div>';
    }).join('');
  }

  modal.appendChild(head);
  modal.appendChild(list);
  overlay.appendChild(modal);
  overlay.addEventListener('click',function(e){ if(e.target===overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

function nbLoadLibrary(){
  try{
    // If the code's built-in seed content has changed since this browser last
    // saved, don't let the old saved snapshot mask the update — reconcile
    // instead of blindly restoring it wholesale.
    var savedVersion=localStorage.getItem(NB_STORAGE_KEYS.seedVersion);
    var seedMatches=(savedVersion===String(NB_SEED_VERSION));

    var docsRaw=localStorage.getItem(NB_STORAGE_KEYS.docs);
    if(docsRaw){
      var savedDocs=JSON.parse(docsRaw);
      window.dynamicDocs=window.dynamicDocs||{};
      Object.keys(savedDocs).forEach(function(k){
        var isSeedDoc=(k.indexOf('pdf_')===0||k==='view-churn-doc');
        if(seedMatches||!isSeedDoc) window.dynamicDocs[k]=savedDocs[k];
      });
    }
    var topicsRaw=localStorage.getItem(NB_STORAGE_KEYS.topics);
    if(topicsRaw){
      var savedTopics=JSON.parse(topicsRaw);
      if(Array.isArray(savedTopics) && savedTopics.length){
        if(seedMatches){
          TOPICS=savedTopics;
        } else {
          // Keep the fresh hardcoded seed topics, but bring back any topics
          // the person actually created themselves through the app.
          savedTopics.filter(function(t){ return t.id>NB_SEED_MAX_TOPIC_ID; }).forEach(function(t){
            if(!TOPICS.some(function(x){return x.id===t.id;})) TOPICS.push(t);
          });
        }
      }
    }
    var trashRaw=localStorage.getItem(NB_STORAGE_KEYS.trash);
    if(trashRaw){
      var savedTrash=JSON.parse(trashRaw);
      if(Array.isArray(savedTrash)) nbTrash=savedTrash;
    }
    if(!seedMatches) nbSaveLibrary(); // stamp the reconciled state with the current version
  }catch(e){ /* localStorage unavailable or corrupt — start fresh */ }
}

function nbSaveDraft(){
  try{
    localStorage.setItem(NB_STORAGE_KEYS.draft, JSON.stringify({
      state:nbState,
      custom:nbCustomStages,
      seq:nbCustomStageSeq,
      order:nbStageOrder,
      editingId:window.nbEditingDocId||null,
      linkTopicId:window.nbLinkToTopicId||null
    }));
  }catch(e){ /* localStorage unavailable — fail silently */ }
}

function nbLoadDraft(){
  try{
    var raw=localStorage.getItem(NB_STORAGE_KEYS.draft);
    if(!raw) return;
    var d=JSON.parse(raw);
    if(d.state) nbState=d.state;
    if(d.custom) nbCustomStages=d.custom;
    if(typeof d.seq==='number') nbCustomStageSeq=d.seq;
    if(d.order) nbStageOrder=d.order;
    if(d.editingId) window.nbEditingDocId=d.editingId;
    if(d.linkTopicId) window.nbLinkToTopicId=d.linkTopicId;
  }catch(e){ /* localStorage unavailable or corrupt — start fresh */ }
}

// Safety net: also save right before the tab/page closes or refreshes
window.addEventListener('beforeunload', nbSaveDraft);

