// Single delegated listener for option clicks
document.addEventListener('click', function(e){
  var opt = e.target.closest('.nb-opt');
  if(!opt) return;
  // Only handle if it has data-s and data-i (checkbox options, not radio items)
  var sid = opt.getAttribute('data-s');
  var idx = parseInt(opt.getAttribute('data-i'));
  if(!sid || isNaN(idx)) return;
  // Make sure this stage has options (not s1 fields type)
  var stageDef = nbGetAllStages().filter(function(x){return x.id===sid;})[0];
  if(!stageDef || stageDef.type==='fields') return;
  e.stopPropagation();
  nbPickOpt(sid, idx);
});
// ── IMAGE UPLOAD HANDLING ────────────────────────────────────────────────
document.addEventListener('change', function(e){
  var input = e.target;
  if(input.type !== 'file' || !input.files[0]) return;
  
  var sid = input.getAttribute('data-sid');
  var idx = input.getAttribute('data-idx');
  if(!sid) return;
  
  var file = input.files[0];
  var reader = new FileReader();
  reader.onload = function(ev){
    var dataUrl = ev.target.result;
    if(!nbState[sid]) return;
    if(!nbState[sid].images) nbState[sid].images = {};
    
    var key = (idx !== null && idx !== 'custom') ? parseInt(idx) : 'stage_' + Date.now();
    nbState[sid].images[key] = dataUrl;
    
    // Show preview
    var uid = 'nb-opt-' + sid + '-' + idx;
    var previewEl = document.getElementById('nb-opt-imgs-' + uid);
    if(previewEl){
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:relative;display:inline-block;margin-top:8px';
      wrap.setAttribute('data-key', key);
      var img = document.createElement('img');
      img.src = dataUrl;
      img.style.cssText = 'max-width:100%;max-height:180px;width:auto;border-radius:6px;border:1px solid var(--border);display:block';
      nbMakeZoomable(img);
      var del = document.createElement('button');
      del.textContent = '×';
      del.style.cssText = 'position:absolute;top:2px;right:2px;background:var(--red);color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:12px;cursor:pointer;line-height:18px;padding:0;text-align:center';
      del.addEventListener('click', function(e){
        e.stopPropagation();
        delete nbState[sid].images[key];
        wrap.remove();
      });
      wrap.appendChild(img);
      wrap.appendChild(del);
      previewEl.appendChild(wrap);
    }
    
    // Stage-level image container
    var stageImgsEl = document.getElementById('nb-imgs-' + sid);
    if(stageImgsEl && (idx === null || idx === 'custom')){
      var wrap2 = document.createElement('div');
      wrap2.style.cssText = 'position:relative;display:block;margin-top:8px;width:100%';
      var img2 = document.createElement('img');
      img2.src = dataUrl;
      img2.style.cssText = 'width:100%;max-height:300px;object-fit:contain;border-radius:6px;border:1px solid var(--border);display:block;background:#f9f9f9';
      var del2 = document.createElement('button');
      del2.textContent = '×';
      del2.style.cssText = 'position:absolute;top:2px;right:2px;background:var(--red);color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:12px;cursor:pointer;line-height:18px;padding:0;text-align:center';
      del2.addEventListener('click', function(e){
        e.stopPropagation();
        delete nbState[sid].images[key];
        wrap2.remove();
      });
      wrap2.appendChild(img2);
      wrap2.appendChild(del2);
      stageImgsEl.appendChild(wrap2);
    }
    
    input.value = ''; // allow re-select same file
  };
  reader.readAsDataURL(file);
});
